package net.kdt.pojavlaunch.fragments;

import android.os.Bundle;import android.view.View;import android.widget.LinearLayout;import android.widget.TextView;
import androidx.annotation.NonNull;import androidx.annotation.Nullable;import androidx.fragment.app.Fragment;
import net.kdt.pojavlaunch.R;import net.kdt.pojavlaunch.Tools;import net.kdt.pojavlaunch.UiMotion;import net.kdt.pojavlaunch.csclient.*;import java.util.ArrayList;

public class CsClientBuilderFragment extends Fragment{
 public static final String TAG="CS_CLIENT_BUILDER";private CsClientCatalog.VersionEntry version;private LinearLayout manifest;
 public CsClientBuilderFragment(){super(R.layout.fragment_cs_client_builder);}
 @Override public void onCreate(@Nullable Bundle s){super.onCreate(s);version=(CsClientCatalog.VersionEntry)requireArguments().getSerializable("version");}
 @Override public void onViewCreated(@NonNull View r,@Nullable Bundle s){manifest=r.findViewById(R.id.csc_selection_chips);((TextView)r.findViewById(R.id.csc_builder_version)).setText("MINECRAFT "+version.minecraft);((TextView)r.findViewById(R.id.csc_builder_build)).setText("CS CLIENT "+version.build+"  •  FABRIC");r.findViewById(R.id.csc_builder_back).setOnClickListener(v->requireActivity().getSupportFragmentManager().popBackStack());r.findViewById(R.id.csc_browse_mods).setOnClickListener(v->openPicker(false));r.findViewById(R.id.csc_browse_pack).setOnClickListener(v->openPicker(true));r.findViewById(R.id.csc_create_profile).setOnClickListener(v->openInstall());UiMotion.pressFeedback(r.findViewById(R.id.csc_builder_back),r.findViewById(R.id.csc_browse_mods),r.findViewById(R.id.csc_browse_pack),r.findViewById(R.id.csc_create_profile));enter(r.findViewById(R.id.csc_builder_identity),0,-12);enter(r.findViewById(R.id.csc_builder_manifest),55,12);refresh();}
 @Override public void onResume(){super.onResume();if(manifest!=null)refresh();}
 private void openPicker(boolean pack){Bundle b=new Bundle();b.putString("mc",version.minecraft);b.putBoolean("pack",pack);Tools.swapFragment(requireActivity(),CsClientPickerFragment.class,CsClientPickerFragment.TAG,b);}
 private void openInstall(){Bundle b=new Bundle();b.putSerializable("version",version);Tools.swapFragment(requireActivity(),CsClientInstallFragment.class,CsClientInstallFragment.TAG,b);}
 private void refresh(){manifest.removeAllViews();addRow("FABRIC LOADER","Compatible stable channel",null,true,0);addRow("CS CLIENT",version.build,null,true,25);addRow("FABRIC API","Always included",null,true,50);int d=75;if(CsClientSelection.modpack!=null){CsClientCatalog.ProjectEntry e=CsClientSelection.modpack;addRow(e.title,"SELECTED MODPACK",()->{CsClientSelection.modpack=null;refresh();},true,d);d+=25;}for(CsClientCatalog.ProjectEntry e:new ArrayList<>(CsClientSelection.mods)){addRow(e.title,"FABRIC MODULE",()->{CsClientSelection.toggleMod(e);refresh();},true,d);d+=25;}}
 private void addRow(String title,String sub,@Nullable Runnable remove,boolean checked,long delay){LinearLayout row=new LinearLayout(requireContext());row.setOrientation(LinearLayout.HORIZONTAL);row.setGravity(android.view.Gravity.CENTER_VERTICAL);row.setPadding(dp(14),0,dp(12),0);row.setBackgroundResource(R.drawable.bg_csc_manifest_row);LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,dp(50));lp.bottomMargin=dp(7);row.setLayoutParams(lp);TextView mark=t(checked?"✓":"•",14,0xffffffff,true);row.addView(mark,new LinearLayout.LayoutParams(dp(28),-1));LinearLayout box=new LinearLayout(requireContext());box.setOrientation(LinearLayout.VERTICAL);box.setGravity(android.view.Gravity.CENTER_VERTICAL);TextView titleView=t(title,11,0xfff2f3f5,true);TextView subView=t(sub,7,0xff858e98,false);box.addView(titleView,new LinearLayout.LayoutParams(-1,dp(21)));box.addView(subView,new LinearLayout.LayoutParams(-1,dp(15)));row.addView(box,new LinearLayout.LayoutParams(0,-1,1));if(remove!=null){TextView x=t("×",18,0xffaeb5bd,false);x.setGravity(android.view.Gravity.CENTER);row.addView(x,new LinearLayout.LayoutParams(dp(40),-1));row.setOnClickListener(v->row.animate().alpha(0).translationX(dp(12)).setDuration(130).withEndAction(remove).start());}manifest.addView(row);enter(row,delay,8);}
 private TextView t(String s,int z,int c,boolean b){TextView v=new TextView(requireContext());v.setText(s);v.setTextSize(z);v.setTextColor(c);if(b)v.setTypeface(null,1);v.setGravity(android.view.Gravity.CENTER_VERTICAL);v.setIncludeFontPadding(false);v.setSingleLine(true);v.setEllipsize(android.text.TextUtils.TruncateAt.END);return v;}
 private void enter(View v,long delay,float x){v.setAlpha(0);v.setTranslationX(dp((int)x));v.animate().alpha(1).translationX(0).setStartDelay(delay).setDuration(240).start();}private int dp(int n){return Math.round(n*getResources().getDisplayMetrics().density);}
}
